async function handleMultipleUpload(req, res) {
  const uploadedFiles = [];
  const errors = [];

  try {
    if (!req.files || req.files.length === 0) {
      return res.status(400).json({ error: 'No files uploaded' });
    }

    // Process each file
    for (const file of req.files) {
      try {
        // Verify file type
        await verifyFileType(file.path, ['image/jpeg', 'image/png', 'image/gif']);

        // Scan for viruses
        await scanFile(file.path);

        // Process image if applicable
        if (file.mimetype.startsWith('image/')) {
          await processImage(file.path);
        }

        // Move to permanent storage
        const permanentPath = await moveToStorage(file);

        // Save metadata
        const fileRecord = await saveFileMetadata({
          originalName: file.originalname,
          storedName: path.basename(permanentPath),
          size: file.size,
          mimeType: file.mimetype,
          uploadedBy: req.user.id,
          uploadedAt: new Date()
        });

        uploadedFiles.push({
          id: fileRecord.id,
          name: file.originalname,
          size: file.size
        });

      } catch (error) {
        // Clean up failed file
        await fs.unlink(file.path).catch(() => {});

        errors.push({
          filename: file.originalname,
          error: error.message
        });
      }
    }

    // Return results
    res.json({
      success: uploadedFiles.length > 0,
      uploaded: uploadedFiles,
      errors: errors,
      summary: {
        total: req.files.length,
        successful: uploadedFiles.length,
        failed: errors.length
      }
    });

  } catch (error) {
    // Clean up all files on catastrophic failure
    if (req.files) {
      for (const file of req.files) {
        await fs.unlink(file.path).catch(() => {});
      }
    }

