**4. Alternative: Chunked Upload for Large Files:**

```javascript
// Server-side chunked upload handler
app.post('/upload/chunk', async (req, res) => {
  const { chunkIndex, totalChunks, filename, uploadId } = req.body;
  const chunk = req.files.chunk;

  const uploadDir = path.join('./uploads/chunks/', uploadId);
  await fs.mkdir(uploadDir, { recursive: true });

  const chunkPath = path.join(uploadDir, `chunk-${chunkIndex}`);
  await fs.rename(chunk.path, chunkPath);

  // Check if all chunks received
  if (parseInt(chunkIndex) === parseInt(totalChunks) - 1) {
    // Combine chunks
    const finalPath = await combineChunks(uploadDir, filename, totalChunks);

    // Clean up chunks
    await fs.rm(uploadDir, { recursive: true });

    res.json({ 
      complete: true, 
      path: finalPath 
    });
  } else {
    res.json({ 
      complete: false, 
      received: parseInt(chunkIndex) + 1,
      total: totalChunks
    });
  }
});

async function combineChunks(uploadDir, filename, totalChunks) {
  const finalPath = path.join('./uploads/', crypto.randomBytes(16).toString('hex') + path.extname(filename));
  const writeStream = fs.createWriteStream(finalPath);

  for (let i = 0; i < totalChunks; i++) {
    const chunkPath = path.join(uploadDir, `chunk-${i}`);
    const chunkBuffer = await fs.readFile(chunkPath);
    writeStream.write(chunkBuffer);
  }

  writeStream.end();

  return new Promise((resolve, reject) => {
    writeStream.on('finish', () => resolve(finalPath));
    writeStream.on('error', reject);
  });
}
```

