class UploadManager {
  constructor() {
    this.activeUploads = new Map();
  }

  async uploadFile(file, onProgress) {
    const uploadId = this.generateUploadId();
    const abortController = new AbortController();

    // Store controller for later cancellation
    this.activeUploads.set(uploadId, {
      controller: abortController,
      filename: file.name,
      startTime: Date.now()
    });

    const formData = new FormData();
    formData.append('file', file);
    formData.append('uploadId', uploadId);

    try {
      const response = await fetch('/upload', {
        method: 'POST',
        body: formData,
        signal: abortController.signal,
        // For progress tracking with fetch
        onUploadProgress: (progressEvent) => {
          const percentage = (progressEvent.loaded / progressEvent.total) * 100;
          if (onProgress) onProgress(percentage);
        }
      });

      if (!response.ok) {
        throw new Error(`Upload failed: ${response.statusText}`);
      }

      const result = await response.json();
      this.activeUploads.delete(uploadId);

      return result;

    } catch (error) {
      if (error.name === 'AbortError') {
        console.log('Upload cancelled:', file.name);
        // Notify server of cancellation
        await this.notifyServerCancellation(uploadId);
      }

      this.activeUploads.delete(uploadId);
      throw error;
    }
  }

  cancelUpload(uploadId) {
    const upload = this.activeUploads.get(uploadId);
    if (upload) {
      upload.controller.abort();
      this.activeUploads.delete(uploadId);
      return true;
    }
    return false;
  }

  cancelAll() {
    for (const [uploadId, upload] of this.activeUploads) {
      upload.controller.abort();
    }
    this.activeUploads.clear();
  }

  async notifyServerCancellation(uploadId) {
    try {
      await fetch('/upload/cancel', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ uploadId })
      });
    } catch (error) {
      console.error('Failed to notify server of cancellation:', error);
    }
  }

  generateUploadId() {
    return `upload-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

