**Using XMLHttpRequest for Better Progress Control:**
```javascript
class XHRUploadManager {
  constructor() {
    this.activeUploads = new Map();
  }

  uploadFile(file, callbacks = {}) {
    return new Promise((resolve, reject) => {
      const uploadId = this.generateUploadId();
      const xhr = new XMLHttpRequest();

      // Store XHR for cancellation
      this.activeUploads.set(uploadId, {
        xhr: xhr,
        filename: file.name,
        startTime: Date.now()
      });

      // Progress tracking
      xhr.upload.addEventListener('progress', (e) => {
        if (e.lengthComputable) {
          const percentage = (e.loaded / e.total) * 100;
          const speed = e.loaded / ((Date.now() - this.activeUploads.get(uploadId).startTime) / 1000);
          const remaining = (e.total - e.loaded) / speed;

          if (callbacks.onProgress) {
            callbacks.onProgress({
              uploadId,
              percentage,
              loaded: e.loaded,
              total: e.total,
              speed,
              remaining
            });
          }
        }
      });

      // Upload complete
      xhr.addEventListener('load', () => {
        this.activeUploads.delete(uploadId);

        if (xhr.status >= 200 && xhr.status < 300) {
          try {
            const result = JSON.parse(xhr.responseText);
            resolve(result);
          } catch (error) {
            reject(new Error('Invalid server response'));
          }
        } else {
          reject(new Error(`Upload failed: ${xhr.status}`));
        }
      });

      // Upload error
      xhr.addEventListener('error', () => {
        this.activeUploads.delete(uploadId);
        reject(new Error('Network error during upload'));
      });

      // Upload aborted
      xhr.addEventListener('abort', () => {
        this.activeUploads.delete(uploadId);
        this.notifyServerCancellation(uploadId);
        reject(new Error('Upload cancelled'));
      });

      // Prepare and send
      const formData = new FormData();
      formData.append('file', file);
      formData.append('uploadId', uploadId);

      xhr.open('POST', '/upload');
      xhr.send(formData);
    });
  }

  cancelUpload(uploadId) {
    const upload = this.activeUploads.get(uploadId);
    if (upload && upload.xhr) {
      upload.xhr.abort();
      return true;
    }
    return false;
  }

  getUploadInfo(uploadId) {
    return this.activeUploads.get(uploadId);
  }

  getAllActiveUploads() {
    return Array.from(this.activeUploads.entries()).map(([id, info]) => ({
      uploadId: id,
      filename: info.filename,
      duration: Date.now() - info.startTime
    }));
  }

  async notifyServerCancellation(uploadId) {
    try {
      await fetch('/upload/cancel', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ uploadId })
      });
    } catch (error) {
      console.error('Failed to notify server:', error);
    }
  }

  generateUploadId() {
    return `upload-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}
