    // If complete, assemble file
    if (progress.complete) {
      const finalPath = await assembleFile(metadata);
      progress.filePath = finalPath;

      // Clean up
      await fs.rm(metadata.uploadDir, { recursive: true });
      uploadRegistry.delete(uploadId);
    }

    res.json(progress);

  } catch (error) {
    console.error('Chunk upload error:', error);
