async function restoreUploadMetadata(uploadId) {
  try {
    const uploadDir = path.join('./uploads/resumable/', uploadId);
    const metadataPath = path.join(uploadDir, 'metadata.json');

    const data = await fs.readFile(metadataPath, 'utf8');
    const metadata = JSON.parse(data);

    // Restore Set from array
    metadata.uploadedChunks = new Set(metadata.uploadedChunks);
    metadata.uploadDir = uploadDir;

    uploadRegistry.set(uploadId, metadata);
    return metadata;
  } catch (error) {
    return null;
