async function assembleFile(metadata) {
  const finalFilename = crypto.randomBytes(16).toString('hex') + 
                        path.extname(metadata.filename);
  const finalPath = path.join('./uploads/', finalFilename);

  const writeStream = fs.createWriteStream(finalPath);

  // Write chunks in order
  for (let i = 0; i < metadata.totalChunks; i++) {
    const chunkPath = path.join(metadata.uploadDir, `chunk-${i}`);
    const chunkData = await fs.readFile(chunkPath);
    writeStream.write(chunkData);
