const activeUploads = new Map();

// Middleware to track uploads
app.use((req, res, next) => {
  const uploadId = req.body.uploadId || req.query.uploadId;

  if (uploadId && req.method === 'POST' && req.path.startsWith('/upload')) {
    activeUploads.set(uploadId, {
      req,
      res,
      startTime: Date.now(),
      cancelled: false
    });

    // Clean up on response finish
    res.on('finish', () => {
      activeUploads.delete(uploadId);
    });

    // Handle client disconnect
    req.on('close', () => {
      if (!res.finished) {
        console.log('Client disconnected during upload:', uploadId);
        cleanupUpload(uploadId);
        activeUploads.delete(uploadId);
      }
    });
  }

  next();
});

// Cancellation endpoint
app.post('/upload/cancel', async (req, res) => {
  const { uploadId } = req.body;

  const upload = activeUploads.get(uploadId);
  if (upload) {
    upload.cancelled = true;

    // Destroy the request stream
    if (upload.req) {
      upload.req.destroy();
    }

    await cleanupUpload(uploadId);
    activeUploads.delete(uploadId);

    res.json({ success: true, message: 'Upload cancelled' });
  } else {
    res.status(404).json({ error: 'Upload not found' });
  }
});

async function cleanupUpload(uploadId) {
