**Server-Side Resumable Upload Implementation:**
```javascript
const crypto = require('crypto');
const fs = require('fs').promises;
const path = require('path');

// Store upload metadata
const uploadRegistry = new Map();

// Initialize resumable upload
app.post('/upload/init', async (req, res) => {
  const { filename, fileSize, mimeType } = req.body;

  // Validate
  if (!filename || !fileSize) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const uploadId = crypto.randomBytes(16).toString('hex');
  const chunkSize = 1024 * 1024; // 1MB chunks
  const totalChunks = Math.ceil(fileSize / chunkSize);

  // Create upload directory
  const uploadDir = path.join('./uploads/resumable/', uploadId);
  await fs.mkdir(uploadDir, { recursive: true });

  // Store metadata
  const metadata = {
    uploadId,
    filename,
    fileSize,
    mimeType,
    chunkSize,
    totalChunks,
    uploadedChunks: new Set(),
    createdAt: Date.now(),
    lastActivity: Date.now(),
    uploadDir
  };

  uploadRegistry.set(uploadId, metadata);

  // Save metadata to disk for persistence
  await fs.writeFile(
    path.join(uploadDir, 'metadata.json'),
    JSON.stringify(metadata, (key, value) => 
      value instanceof Set ? Array.from(value) : value
    )
  );

  res.json({
    uploadId,
    chunkSize,
    totalChunks,
    resumable: true
  });
});

// Upload chunk
app.post('/upload/chunk/:uploadId', async (req, res) => {
  const { uploadId } = req.params;
  const { chunkIndex } = req.body;
  const chunk = req.files?.chunk;

  if (!chunk) {
    return res.status(400).json({ error: 'No chunk provided' });
  }

  // Get or restore metadata
  let metadata = uploadRegistry.get(uploadId);
  if (!metadata) {
    metadata = await restoreUploadMetadata(uploadId);
    if (!metadata) {
      return res.status(404).json({ error: 'Upload not found' });
    }
  }

  const chunkPath = path.join(metadata.uploadDir, `chunk-${chunkIndex}`);

  try {
    // Save chunk
    await fs.rename(chunk.path, chunkPath);

    // Update metadata
    metadata.uploadedChunks.add(parseInt(chunkIndex));
    metadata.lastActivity = Date.now();

    // Save updated metadata
    await fs.writeFile(
      path.join(metadata.uploadDir, 'metadata.json'),
      JSON.stringify(metadata, (key, value) => 
        value instanceof Set ? Array.from(value) : value
      )
    );

    const progress = {
      uploadId,
      chunkIndex: parseInt(chunkIndex),
      uploadedChunks: metadata.uploadedChunks.size,
      totalChunks: metadata.totalChunks,
      percentage: (metadata.uploadedChunks.size / metadata.totalChunks) * 100,
      complete: metadata.uploadedChunks.size === metadata.totalChunks
    };

    // If complete, assemble file
    if (progress.complete) {
      const finalPath = await assembleFile(metadata);
      progress.filePath = finalPath;

      // Clean up
      await fs.rm(metadata.uploadDir, { recursive: true });
      uploadRegistry.delete(uploadId);
    }

    res.json(progress);

  } catch (error) {
    console.error('Chunk upload error:', error);
    res.status(500).json({ error: 'Failed to save chunk' });
  }
});

// Get upload status (for resuming)
app.get('/upload/status/:uploadId', async (req, res) => {
  const { uploadId } = req.params;

  let metadata = uploadRegistry.get(uploadId);
  if (!metadata) {
    metadata = await restoreUploadMetadata(uploadId);
    if (!metadata) {
      return res.status(404).json({ error: 'Upload not found' });
    }
  }

  res.json({
    uploadId,
    filename: metadata.filename,
    fileSize: metadata.fileSize,
    chunkSize: metadata.chunkSize,
    totalChunks: metadata.totalChunks,
    uploadedChunks: Array.from(metadata.uploadedChunks),
    missingChunks: getMissingChunks(metadata),
    percentage: (metadata.uploadedChunks.size / metadata.totalChunks) * 100,
    complete: metadata.uploadedChunks.size === metadata.totalChunks
  });
});

// Helper functions
async function restoreUploadMetadata(uploadId) {
  try {
    const uploadDir = path.join('./uploads/resumable/', uploadId);
    const metadataPath = path.join(uploadDir, 'metadata.json');

    const data = await fs.readFile(metadataPath, 'utf8');
    const metadata = JSON.parse(data);

    // Restore Set from array
    metadata.uploadedChunks = new Set(metadata.uploadedChunks);
    metadata.uploadDir = uploadDir;

    uploadRegistry.set(uploadId, metadata);
    return metadata;
  } catch (error) {
    return null;
  }
}

function getMissingChunks(metadata) {
  const missing = [];
  for (let i = 0; i < metadata.totalChunks; i++) {
    if (!metadata.uploadedChunks.has(i)) {
      missing.push(i);
    }
  }
  return missing;
}

async function assembleFile(metadata) {
  const finalFilename = crypto.randomBytes(16).toString('hex') + 
                        path.extname(metadata.filename);
  const finalPath = path.join('./uploads/', finalFilename);

  const writeStream = fs.createWriteStream(finalPath);

  // Write chunks in order
  for (let i = 0; i < metadata.totalChunks; i++) {
    const chunkPath = path.join(metadata.uploadDir, `chunk-${i}`);
    const chunkData = await fs.readFile(chunkPath);
    writeStream.write(chunkData);
  }

  writeStream.end();

  return new Promise((resolve, reject) => {
    writeStream.on('finish', () => resolve(finalPath));
    writeStream.on('error', reject);
  });
}

// Cleanup old incomplete uploads (run periodically)
async function cleanupStaleUploads() {
  const maxAge = 24 * 60 * 60 * 1000; // 24 hours
  const now = Date.now();

  for (const [uploadId, metadata] of uploadRegistry.entries()) {
    if (now - metadata.lastActivity > maxAge) {
      await fs.rm(metadata.uploadDir, { recursive: true, force: true });
      uploadRegistry.delete(uploadId);
      console.log('Cleaned up stale upload:', uploadId);
    }
  }
}

// Run cleanup every hour
setInterval(cleanupStaleUploads, 60 * 60 * 1000);
