**Client-Side Resumable Upload:**
```javascript
class ResumableUpload {
  constructor(file, options = {}) {
    this.file = file;
    this.chunkSize = options.chunkSize || 1024 * 1024; // 1MB
    this.uploadId = null;
    this.totalChunks = Math.ceil(file.size / this.chunkSize);
    this.uploadedChunks = new Set();
    this.onProgress = options.onProgress;
    this.onComplete = options.onComplete;
    this.onError = options.onError;
    this.paused = false;
    this.cancelled = false;
  }

  async start() {
    try {
      // Check if we can resume
      const savedUploadId = this.getSavedUploadId();

      if (savedUploadId) {
        // Try to resume
        const canResume = await this.resume(savedUploadId);
        if (!canResume) {
          // Start new upload
          await this.initialize();
        }
      } else {
        // Start new upload
        await this.initialize();
      }

      // Upload chunks
      await this.uploadChunks();

    } catch (error) {
      if (this.onError) this.onError(error);
      throw error;
    }
  }

  async initialize() {
    const response = await fetch('/upload/init', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        filename: this.file.name,
        fileSize: this.file.size,
        mimeType: this.file.type
      })
    });

    if (!response.ok) {
      throw new Error('Failed to initialize upload');
    }

    const data = await response.json();
    this.uploadId = data.uploadId;
    this.chunkSize = data.chunkSize;
    this.totalChunks = data.totalChunks;

    // Save upload ID for resuming
    this.saveUploadId(this.uploadId);

    return data;
  }

  async resume(uploadId) {
    try {
      const response = await fetch(`/upload/status/${uploadId}`);

      if (!response.ok) {
        return false;
      }

      const status = await response.json();

      // Verify file matches
      if (status.filename !== this.file.name || 
          status.fileSize !== this.file.size) {
        return false;
      }

      this.uploadId = uploadId;
      this.chunkSize = status.chunkSize;
      this.totalChunks = status.totalChunks;
      this.uploadedChunks = new Set(status.uploadedChunks);

      console.log(`Resuming upload: ${this.uploadedChunks.size}/${this.totalChunks} chunks already uploaded`);

      return true;

    } catch (error) {
      console.error('Resume failed:', error);
      return false;
    }
  }

  async uploadChunks() {
    for (let i = 0; i < this.totalChunks; i++) {
      // Check if cancelled
      if (this.cancelled) {
        throw new Error('Upload cancelled');
      }

      // Wait if paused
      while (this.paused) {
        await new Promise(resolve => setTimeout(resolve, 100));
      }

      // Skip if already uploaded
      if (this.uploadedChunks.has(i)) {
        continue;
      }

      // Upload chunk
      await this.uploadChunk(i);
    }

    // Clear saved upload ID
    this.clearSavedUploadId();

    if (this.onComplete) {
      this.onComplete();
    }
  }

  async uploadChunk(chunkIndex) {
    const start = chunkIndex * this.chunkSize;
    const end = Math.min(start + this.chunkSize, this.file.size);
    const chunk = this.file.slice(start, end);

    const formData = new FormData();
    formData.append('chunk', chunk);
    formData.append('chunkIndex', chunkIndex);

    const response = await fetch(`/upload/chunk/${this.uploadId}`, {
      method: 'POST',
      body: formData
    });

    if (!response.ok) {
      throw new Error(`Failed to upload chunk ${chunkIndex}`);
    }

    const result = await response.json();
    this.uploadedChunks.add(chunkIndex);

    if (this.onProgress) {
      this.onProgress({
        chunkIndex,
        uploadedChunks: this.uploadedChunks.size,
        totalChunks: this.totalChunks,
        percentage: result.percentage,
        complete: result.complete
      });
    }

    return result;
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  cancel() {
    this.cancelled = true;
    this.clearSavedUploadId();
  }

  saveUploadId(uploadId) {
    const key = `resumable_upload_${this.getFileHash()}`;
    localStorage.setItem(key, uploadId);
  }

  getSavedUploadId() {
    const key = `resumable_upload_${this.getFileHash()}`;
    return localStorage.getItem(key);
  }

  clearSavedUploadId() {
    const key = `resumable_upload_${this.getFileHash()}`;
    localStorage.removeItem(key);
  }

  getFileHash() {
    // Simple hash based on file properties
    return `${this.file.name}_${this.file.size}_${this.file.lastModified}`;
  }
}

